    CONSTRAINT sales_plan_area_id_fkey FOREIGN KEY (area_id) REFERENCES hartland.area (area_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.supply_plan (
    month date NOT NULL,
    sku_id bigint NOT NULL,
    dc_site_id bigint NOT NULL,
    planned_cases numeric(12,3) NOT NULL,
