    CONSTRAINT supply_plan_sku_id_fkey FOREIGN KEY (sku_id) REFERENCES hartland.sku (sku_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT supply_plan_dc_site_id_fkey FOREIGN KEY (dc_site_id) REFERENCES hartland.site (site_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.stock_policy (
    stock_policy_id bigint NOT NULL,
    sku_id bigint NOT NULL,
    dc_site_id bigint NOT NULL,
    min_days_cover numeric(5,1) NOT NULL,
    max_days_cover numeric(5,1) NOT NULL,
    valid_from date NOT NULL,
    valid_to date NOT NULL,
    CONSTRAINT stock_policy_pkey PRIMARY KEY (stock_policy_id),
    CONSTRAINT stock_policy_sku_id_fkey FOREIGN KEY (sku_id) REFERENCES hartland.sku (sku_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT stock_policy_dc_site_id_fkey FOREIGN KEY (dc_site_id) REFERENCES hartland.site (site_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.prompt_rule (
    prompt_rule_id bigint NOT NULL,
