    kind text NOT NULL CHECK (kind IN ('mandatory_promotion', 'unsupplied_items', 'pos_placement', 'competitor_response', 'ai_tip', 'debt')),
    parameters text NOT NULL,
    priority integer NOT NULL,
    is_mandatory boolean NOT NULL,
    is_adaptable boolean NOT NULL,
    valid_from date NOT NULL,
    valid_to date NOT NULL,
    owner_employee_id bigint NOT NULL,
    document_id bigint,
    CONSTRAINT prompt_rule_pkey PRIMARY KEY (prompt_rule_id),
    CONSTRAINT prompt_rule_owner_employee_id_fkey FOREIGN KEY (owner_employee_id) REFERENCES hartland.employee (employee_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT prompt_rule_document_id_fkey FOREIGN KEY (document_id) REFERENCES hartland.document (document_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.lifecycle_rule (
    lifecycle_rule_id bigint NOT NULL,
    phase text NOT NULL CHECK (phase IN ('potential', 'occasional', 'regular', 'vip', 'lost')),
    rule_kind text NOT NULL CHECK (rule_kind IN ('contact_frequency', 'concessions', 'listing_sequence')),
    parameters text NOT NULL,
    valid_from date NOT NULL,
    valid_to date NOT NULL,
    document_id bigint,
    CONSTRAINT lifecycle_rule_pkey PRIMARY KEY (lifecycle_rule_id),
    CONSTRAINT lifecycle_rule_document_id_fkey FOREIGN KEY (document_id) REFERENCES hartland.document (document_id) DEFERRABLE INITIALLY DEFERRED
);

-- ── org ─────────────────────────────────────────────────────────────────────────────────────────────────

CREATE TABLE hartland.assignment (
    assignment_id bigint NOT NULL,
