    customer_id bigint,
    product_line_id bigint,
    site_id bigint,
    valid_from date NOT NULL,
    valid_to date NOT NULL,
    CONSTRAINT assignment_pkey PRIMARY KEY (assignment_id),
    CONSTRAINT assignment_employee_id_fkey FOREIGN KEY (employee_id) REFERENCES hartland.employee (employee_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT assignment_area_id_fkey FOREIGN KEY (area_id) REFERENCES hartland.area (area_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT assignment_region_id_fkey FOREIGN KEY (region_id) REFERENCES hartland.region (region_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT assignment_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES hartland.customer (customer_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT assignment_product_line_id_fkey FOREIGN KEY (product_line_id) REFERENCES hartland.product_line (product_line_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT assignment_site_id_fkey FOREIGN KEY (site_id) REFERENCES hartland.site (site_id) DEFERRABLE INITIALLY DEFERRED
);

-- ── marketing ───────────────────────────────────────────────────────────────────────────────────────────

CREATE TABLE hartland.campaign (
    campaign_id bigint NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    product_line_id bigint NOT NULL,
    valid_from date NOT NULL,
    valid_to date NOT NULL,
    has_tv boolean NOT NULL,
    has_outdoor boolean NOT NULL,
    has_digital boolean NOT NULL,
    has_instore boolean NOT NULL,
    budget numeric(14,2) NOT NULL,
    owner_employee_id bigint NOT NULL,
    document_id bigint,
    CONSTRAINT campaign_pkey PRIMARY KEY (campaign_id),
    CONSTRAINT campaign_code_key UNIQUE (code),
    CONSTRAINT campaign_product_line_id_fkey FOREIGN KEY (product_line_id) REFERENCES hartland.product_line (product_line_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT campaign_owner_employee_id_fkey FOREIGN KEY (owner_employee_id) REFERENCES hartland.employee (employee_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT campaign_document_id_fkey FOREIGN KEY (document_id) REFERENCES hartland.document (document_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.promotion (
    promotion_id bigint NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    campaign_id bigint,
    goal text NOT NULL,
    target_product_line_id bigint,
    target_sku_id bigint,
    target_uplift_pct numeric(6,2) NOT NULL,
    target_period_weeks integer NOT NULL,
    estimated_budget numeric(14,2) NOT NULL,
    valid_from date NOT NULL,
    valid_to date NOT NULL,
    mechanic text NOT NULL CHECK (mechanic IN ('price_off', 'conditional_price_off', 'free_goods_same', 'free_goods_other')),
    discount_pct numeric(5,2),
    condition_sku_id bigint,
    condition_qty numeric(12,3),
    reward_sku_id bigint,
    reward_qty numeric(12,3),
    is_mandatory boolean NOT NULL,
    is_pre_stocking boolean NOT NULL,
    owner_employee_id bigint NOT NULL,
    status text NOT NULL CHECK (status IN ('draft', 'approved', 'running', 'closed')),
    document_id bigint,
    CONSTRAINT promotion_pkey PRIMARY KEY (promotion_id),
    CONSTRAINT promotion_code_key UNIQUE (code),
    CONSTRAINT promotion_campaign_id_fkey FOREIGN KEY (campaign_id) REFERENCES hartland.campaign (campaign_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT promotion_target_product_line_id_fkey FOREIGN KEY (target_product_line_id) REFERENCES hartland.product_line (product_line_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT promotion_target_sku_id_fkey FOREIGN KEY (target_sku_id) REFERENCES hartland.sku (sku_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT promotion_condition_sku_id_fkey FOREIGN KEY (condition_sku_id) REFERENCES hartland.sku (sku_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT promotion_reward_sku_id_fkey FOREIGN KEY (reward_sku_id) REFERENCES hartland.sku (sku_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT promotion_owner_employee_id_fkey FOREIGN KEY (owner_employee_id) REFERENCES hartland.employee (employee_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT promotion_document_id_fkey FOREIGN KEY (document_id) REFERENCES hartland.document (document_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.promotion_eligibility (
    promotion_eligibility_id bigint NOT NULL,
    promotion_id bigint NOT NULL,
    scope_kind text NOT NULL CHECK (scope_kind IN ('channel', 'chain', 'region', 'store_class', 'phase')),
    scope_value text NOT NULL,
    CONSTRAINT promotion_eligibility_pkey PRIMARY KEY (promotion_eligibility_id),
    CONSTRAINT promotion_eligibility_promotion_id_fkey FOREIGN KEY (promotion_id) REFERENCES hartland.promotion (promotion_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.promotion_exclusion (
    promotion_id bigint NOT NULL,
    excluded_promotion_id bigint NOT NULL,
    CONSTRAINT promotion_exclusion_pkey PRIMARY KEY (promotion_id, excluded_promotion_id),
    CONSTRAINT promotion_exclusion_promotion_id_fkey FOREIGN KEY (promotion_id) REFERENCES hartland.promotion (promotion_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT promotion_exclusion_excluded_promotion_id_fkey FOREIGN KEY (excluded_promotion_id) REFERENCES hartland.promotion (promotion_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.seasonal_exclusion (
    product_line_id bigint NOT NULL,
    month_of_year integer NOT NULL,
    CONSTRAINT seasonal_exclusion_pkey PRIMARY KEY (product_line_id, month_of_year),
    CONSTRAINT seasonal_exclusion_product_line_id_fkey FOREIGN KEY (product_line_id) REFERENCES hartland.product_line (product_line_id) DEFERRABLE INITIALLY DEFERRED
);

