    CONSTRAINT pos_material_product_line_id_fkey FOREIGN KEY (product_line_id) REFERENCES hartland.product_line (product_line_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.pos_asset (
    pos_asset_id bigint NOT NULL,
    pos_material_id bigint NOT NULL,
    asset_no text NOT NULL,
    acquired_on date NOT NULL,
    cost numeric(14,2) NOT NULL,
    region_id bigint NOT NULL,
    condition text NOT NULL CHECK (condition IN ('new', 'good', 'worn', 'damaged')),
    written_off_on date,
    CONSTRAINT pos_asset_pkey PRIMARY KEY (pos_asset_id),
    CONSTRAINT pos_asset_asset_no_key UNIQUE (asset_no),
    CONSTRAINT pos_asset_pos_material_id_fkey FOREIGN KEY (pos_material_id) REFERENCES hartland.pos_material (pos_material_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT pos_asset_region_id_fkey FOREIGN KEY (region_id) REFERENCES hartland.region (region_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.tourplan (
    tourplan_id bigint NOT NULL,
    employee_id bigint NOT NULL,
    store_id bigint NOT NULL,
    customer_id bigint,
    cycle_weeks integer NOT NULL,
    weekday integer NOT NULL,
    valid_from date NOT NULL,
    valid_to date NOT NULL,
    CONSTRAINT tourplan_pkey PRIMARY KEY (tourplan_id),
    CONSTRAINT tourplan_employee_id_fkey FOREIGN KEY (employee_id) REFERENCES hartland.employee (employee_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT tourplan_store_id_fkey FOREIGN KEY (store_id) REFERENCES hartland.store (store_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT tourplan_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES hartland.customer (customer_id) DEFERRABLE INITIALLY DEFERRED
);

