CREATE TABLE hartland.supplier (
    supplier_id bigint NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    kind text NOT NULL CHECK (kind IN ('factory', 'carrier', 'dc_operator', 'agency', 'admin')),
    legal_entity_id bigint,
    CONSTRAINT supplier_pkey PRIMARY KEY (supplier_id),
    CONSTRAINT supplier_code_key UNIQUE (code),
    CONSTRAINT supplier_legal_entity_id_fkey FOREIGN KEY (legal_entity_id) REFERENCES hartland.legal_entity (legal_entity_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.gl_account (
    gl_account_id bigint NOT NULL,
    code text NOT NULL,
