    CONSTRAINT asset_register_code_key UNIQUE (code),
    CONSTRAINT asset_register_cost_centre_id_fkey FOREIGN KEY (cost_centre_id) REFERENCES hartland.cost_centre (cost_centre_id) DEFERRABLE INITIALLY DEFERRED
);

