    CONSTRAINT menu_item_pkey PRIMARY KEY (menu_item_id),
    CONSTRAINT menu_item_code_key UNIQUE (code),
    CONSTRAINT menu_item_consumes_sku_id_fkey FOREIGN KEY (consumes_sku_id) REFERENCES hartland.sku (sku_id) DEFERRABLE INITIALLY DEFERRED
);

