CREATE TABLE hartland.visit_plan (
    visit_plan_id bigint NOT NULL,
    tourplan_id bigint NOT NULL,
    planned_day date NOT NULL,
    employee_id bigint NOT NULL,
    store_id bigint NOT NULL,
    CONSTRAINT visit_plan_pkey PRIMARY KEY (visit_plan_id),
    CONSTRAINT visit_plan_tourplan_id_fkey FOREIGN KEY (tourplan_id) REFERENCES hartland.tourplan (tourplan_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT visit_plan_employee_id_fkey FOREIGN KEY (employee_id) REFERENCES hartland.employee (employee_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT visit_plan_store_id_fkey FOREIGN KEY (store_id) REFERENCES hartland.store (store_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.visit (
    visit_id bigint NOT NULL,
    visit_plan_id bigint,
    employee_id bigint NOT NULL,
    store_id bigint NOT NULL,
    customer_id bigint,
    day date NOT NULL,
    time_in timestamptz,
    time_out timestamptz,
    kind text NOT NULL CHECK (kind IN ('sales', 'merchandising', 'acquisition')),
    outcome text NOT NULL CHECK (outcome IN ('order', 'no_order', 'closed', 'refused', 'not_found')),
    note text,
    recorded boolean NOT NULL,
    CONSTRAINT visit_pkey PRIMARY KEY (visit_id),
    CONSTRAINT visit_visit_plan_id_fkey FOREIGN KEY (visit_plan_id) REFERENCES hartland.visit_plan (visit_plan_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT visit_employee_id_fkey FOREIGN KEY (employee_id) REFERENCES hartland.employee (employee_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT visit_store_id_fkey FOREIGN KEY (store_id) REFERENCES hartland.store (store_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT visit_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES hartland.customer (customer_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.visit_observation (
    visit_id bigint NOT NULL,
    product_line_id bigint NOT NULL,
    facings integer NOT NULL,
    shelf_share_pct numeric(5,2) NOT NULL,
    out_of_stock boolean NOT NULL,
    secondary_placement boolean NOT NULL,
    promo_compliant boolean,
    competitor_facings integer NOT NULL,
    extra jsonb,
    CONSTRAINT visit_observation_pkey PRIMARY KEY (visit_id, product_line_id),
    CONSTRAINT visit_observation_visit_id_fkey FOREIGN KEY (visit_id) REFERENCES hartland.visit (visit_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT visit_observation_product_line_id_fkey FOREIGN KEY (product_line_id) REFERENCES hartland.product_line (product_line_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.competitor_sighting (
    competitor_sighting_id bigint NOT NULL,
    visit_id bigint NOT NULL,
    competitor_id bigint NOT NULL,
    competitor_product_id bigint,
    activity_kind text NOT NULL CHECK (activity_kind IN ('promotion', 'listing', 'display', 'price_cut')),
    price_seen numeric(14,2),
    description text,
    confirmed boolean NOT NULL,
    CONSTRAINT competitor_sighting_pkey PRIMARY KEY (competitor_sighting_id),
    CONSTRAINT competitor_sighting_visit_id_fkey FOREIGN KEY (visit_id) REFERENCES hartland.visit (visit_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT competitor_sighting_competitor_id_fkey FOREIGN KEY (competitor_id) REFERENCES hartland.competitor (competitor_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT competitor_sighting_competitor_product_id_fkey FOREIGN KEY (competitor_product_id) REFERENCES hartland.competitor_product (competitor_product_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.pos_loan (
    pos_loan_id bigint NOT NULL,
