    lent_on date NOT NULL,
    returned_on date,
    placed_by_employee_id bigint NOT NULL,
    approved_by_employee_id bigint NOT NULL,
    condition_on_return text CHECK (condition_on_return IN ('new', 'good', 'worn', 'damaged')),
    CONSTRAINT pos_loan_pkey PRIMARY KEY (pos_loan_id),
    CONSTRAINT pos_loan_pos_asset_id_fkey FOREIGN KEY (pos_asset_id) REFERENCES hartland.pos_asset (pos_asset_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT pos_loan_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES hartland.customer (customer_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT pos_loan_store_id_fkey FOREIGN KEY (store_id) REFERENCES hartland.store (store_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT pos_loan_placed_by_employee_id_fkey FOREIGN KEY (placed_by_employee_id) REFERENCES hartland.employee (employee_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT pos_loan_approved_by_employee_id_fkey FOREIGN KEY (approved_by_employee_id) REFERENCES hartland.employee (employee_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.pos_handout (
    pos_handout_id bigint NOT NULL,
