    status text NOT NULL CHECK (status IN ('open', 'held', 'released', 'shipped', 'invoiced', 'cancelled')),
    hold_reason text CHECK (hold_reason IN ('credit_limit', 'overdue')),
    dc_site_id bigint NOT NULL,
    CONSTRAINT sales_order_pkey PRIMARY KEY (sales_order_id),
    CONSTRAINT sales_order_order_no_key UNIQUE (order_no),
    CONSTRAINT sales_order_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES hartland.customer (customer_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT sales_order_delivery_point_id_fkey FOREIGN KEY (delivery_point_id) REFERENCES hartland.delivery_point (delivery_point_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT sales_order_taken_by_employee_id_fkey FOREIGN KEY (taken_by_employee_id) REFERENCES hartland.employee (employee_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT sales_order_visit_id_fkey FOREIGN KEY (visit_id) REFERENCES hartland.visit (visit_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT sales_order_dc_site_id_fkey FOREIGN KEY (dc_site_id) REFERENCES hartland.site (site_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.sales_order_line (
    sales_order_line_id bigint NOT NULL,
    sales_order_id bigint NOT NULL,
    line_no integer NOT NULL,
    sku_id bigint NOT NULL,
    qty_cases numeric(12,3) NOT NULL,
    qty_pieces numeric(12,3) NOT NULL,
    list_price_case numeric(14,2) NOT NULL,
    discount_total_case numeric(14,2) NOT NULL,
    discount_total numeric(14,2) NOT NULL,
    invoice_price_case numeric(14,2) NOT NULL,
    is_free_goods boolean NOT NULL,
    purchase_price_case numeric(14,2) NOT NULL,
    inbound_cost_case numeric(14,2) NOT NULL,
    warehouse_cost_case numeric(14,2),
    delivery_cost_case numeric(14,2),
    marketing_cost_case numeric(14,2),
    vat_rate numeric(5,2) NOT NULL,
    CONSTRAINT sales_order_line_pkey PRIMARY KEY (sales_order_line_id),
    CONSTRAINT sales_order_line_sales_order_id_line_no_key UNIQUE (sales_order_id, line_no),
    CONSTRAINT sales_order_line_sales_order_id_fkey FOREIGN KEY (sales_order_id) REFERENCES hartland.sales_order (sales_order_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT sales_order_line_sku_id_fkey FOREIGN KEY (sku_id) REFERENCES hartland.sku (sku_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.sales_order_line_discount (
    sales_order_line_id bigint NOT NULL,
    seq integer NOT NULL,
    kind text NOT NULL CHECK (kind IN ('volume', 'cross_sell', 'agreed', 'individual', 'promotion', 'free_goods', 'retro')),
    code text NOT NULL,
    promotion_id bigint,
    price_agreement_id bigint,
    pct numeric(5,2),
    amount_case numeric(14,2) NOT NULL,
    amount_line numeric(14,2) NOT NULL,
    budget text NOT NULL CHECK (budget IN ('sales', 'marketing')),
    CONSTRAINT sales_order_line_discount_pkey PRIMARY KEY (sales_order_line_id, seq),
    CONSTRAINT sales_order_line_discount_sales_order_line_id_fkey FOREIGN KEY (sales_order_line_id) REFERENCES hartland.sales_order_line (sales_order_line_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT sales_order_line_discount_promotion_id_fkey FOREIGN KEY (promotion_id) REFERENCES hartland.promotion (promotion_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT sales_order_line_discount_price_agreement_id_fkey FOREIGN KEY (price_agreement_id) REFERENCES hartland.price_agreement (price_agreement_id) DEFERRABLE INITIALLY DEFERRED
);

-- ── supply ──────────────────────────────────────────────────────────────────────────────────────────────

CREATE TABLE hartland.purchase_order (
    purchase_order_id bigint NOT NULL,
    po_no text NOT NULL,
    supplier_entity_id bigint NOT NULL,
    dc_site_id bigint NOT NULL,
    ordered_on date NOT NULL,
    requested_on date NOT NULL,
    status text NOT NULL CHECK (status IN ('open', 'confirmed', 'received', 'cancelled')),
    raised_by text NOT NULL CHECK (raised_by IN ('buyer', 'agent')),
    CONSTRAINT purchase_order_pkey PRIMARY KEY (purchase_order_id),
    CONSTRAINT purchase_order_po_no_key UNIQUE (po_no),
    CONSTRAINT purchase_order_supplier_entity_id_fkey FOREIGN KEY (supplier_entity_id) REFERENCES hartland.legal_entity (legal_entity_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT purchase_order_dc_site_id_fkey FOREIGN KEY (dc_site_id) REFERENCES hartland.site (site_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.purchase_order_line (
    purchase_order_line_id bigint NOT NULL,
    purchase_order_id bigint NOT NULL,
    sku_id bigint NOT NULL,
    qty_cases numeric(12,3) NOT NULL,
    purchase_price_case numeric(14,2) NOT NULL,
    CONSTRAINT purchase_order_line_pkey PRIMARY KEY (purchase_order_line_id),
    CONSTRAINT purchase_order_line_purchase_order_id_fkey FOREIGN KEY (purchase_order_id) REFERENCES hartland.purchase_order (purchase_order_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT purchase_order_line_sku_id_fkey FOREIGN KEY (sku_id) REFERENCES hartland.sku (sku_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.inbound_transport (
    inbound_transport_id bigint NOT NULL,
    carrier_id bigint NOT NULL,
    from_site_id bigint NOT NULL,
    to_site_id bigint NOT NULL,
    day date NOT NULL,
    cost numeric(14,2) NOT NULL,
    CONSTRAINT inbound_transport_pkey PRIMARY KEY (inbound_transport_id),
    CONSTRAINT inbound_transport_carrier_id_fkey FOREIGN KEY (carrier_id) REFERENCES hartland.carrier (carrier_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT inbound_transport_from_site_id_fkey FOREIGN KEY (from_site_id) REFERENCES hartland.site (site_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT inbound_transport_to_site_id_fkey FOREIGN KEY (to_site_id) REFERENCES hartland.site (site_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.goods_receipt (
    goods_receipt_id bigint NOT NULL,
    purchase_order_id bigint NOT NULL,
    dc_site_id bigint NOT NULL,
    received_on date NOT NULL,
    inbound_transport_id bigint,
    CONSTRAINT goods_receipt_pkey PRIMARY KEY (goods_receipt_id),
    CONSTRAINT goods_receipt_purchase_order_id_fkey FOREIGN KEY (purchase_order_id) REFERENCES hartland.purchase_order (purchase_order_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT goods_receipt_dc_site_id_fkey FOREIGN KEY (dc_site_id) REFERENCES hartland.site (site_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT goods_receipt_inbound_transport_id_fkey FOREIGN KEY (inbound_transport_id) REFERENCES hartland.inbound_transport (inbound_transport_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.goods_receipt_line (
    goods_receipt_line_id bigint NOT NULL,
    goods_receipt_id bigint NOT NULL,
    sku_id bigint NOT NULL,
    qty_cases numeric(12,3) NOT NULL,
    batch text NOT NULL,
    best_before date NOT NULL,
    CONSTRAINT goods_receipt_line_pkey PRIMARY KEY (goods_receipt_line_id),
    CONSTRAINT goods_receipt_line_goods_receipt_id_fkey FOREIGN KEY (goods_receipt_id) REFERENCES hartland.goods_receipt (goods_receipt_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT goods_receipt_line_sku_id_fkey FOREIGN KEY (sku_id) REFERENCES hartland.sku (sku_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.stock_day (
    sku_id bigint NOT NULL,
    dc_site_id bigint NOT NULL,
    day date NOT NULL,
    on_hand_cases numeric(12,3) NOT NULL,
    reserved_cases numeric(12,3) NOT NULL,
    in_transit_cases numeric(12,3) NOT NULL,
    days_cover numeric(7,1),
    below_min boolean NOT NULL,
    above_max boolean NOT NULL,
    CONSTRAINT stock_day_pkey PRIMARY KEY (sku_id, dc_site_id, day),
    CONSTRAINT stock_day_sku_id_fkey FOREIGN KEY (sku_id) REFERENCES hartland.sku (sku_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT stock_day_dc_site_id_fkey FOREIGN KEY (dc_site_id) REFERENCES hartland.site (site_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.stock_movement (
    stock_movement_id bigint NOT NULL,
    sku_id bigint NOT NULL,
    dc_site_id bigint NOT NULL,
    day date NOT NULL,
    kind text NOT NULL CHECK (kind IN ('receipt', 'pick', 'transfer', 'write_off', 'return_in')),
    qty_cases numeric(12,3) NOT NULL,
    ref_table text,
    ref_id bigint,
    CONSTRAINT stock_movement_pkey PRIMARY KEY (stock_movement_id),
    CONSTRAINT stock_movement_sku_id_fkey FOREIGN KEY (sku_id) REFERENCES hartland.sku (sku_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT stock_movement_dc_site_id_fkey FOREIGN KEY (dc_site_id) REFERENCES hartland.site (site_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.stockout (
    stockout_id bigint NOT NULL,
    sku_id bigint NOT NULL,
    dc_site_id bigint NOT NULL,
    from_day date NOT NULL,
    to_day date,
    lost_order_lines integer NOT NULL,
    CONSTRAINT stockout_pkey PRIMARY KEY (stockout_id),
    CONSTRAINT stockout_sku_id_fkey FOREIGN KEY (sku_id) REFERENCES hartland.sku (sku_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT stockout_dc_site_id_fkey FOREIGN KEY (dc_site_id) REFERENCES hartland.site (site_id) DEFERRABLE INITIALLY DEFERRED
);

-- ── delivery ────────────────────────────────────────────────────────────────────────────────────────────

CREATE TABLE hartland.shipment (
    shipment_id bigint NOT NULL,
    sales_order_id bigint NOT NULL,
    dc_site_id bigint NOT NULL,
    delivery_point_id bigint NOT NULL,
    planned_day date NOT NULL,
    cases numeric(12,3) NOT NULL,
    weight_kg numeric(10,1) NOT NULL,
    status text NOT NULL CHECK (status IN ('planned', 'loaded', 'delivered', 'partial', 'failed', 'rescheduled')),
    delivered_at timestamptz,
    otif boolean,
    CONSTRAINT shipment_pkey PRIMARY KEY (shipment_id),
    CONSTRAINT shipment_sales_order_id_fkey FOREIGN KEY (sales_order_id) REFERENCES hartland.sales_order (sales_order_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT shipment_dc_site_id_fkey FOREIGN KEY (dc_site_id) REFERENCES hartland.site (site_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT shipment_delivery_point_id_fkey FOREIGN KEY (delivery_point_id) REFERENCES hartland.delivery_point (delivery_point_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.route (
    route_id bigint NOT NULL,
    dc_site_id bigint NOT NULL,
    day date NOT NULL,
    carrier_id bigint NOT NULL,
    vehicle_id bigint,
    version integer NOT NULL,
    superseded_by_route_id bigint,
    planned_departure timestamptz NOT NULL,
    planned_km numeric(8,1) NOT NULL,
    planned_stops integer NOT NULL,
    planned_cost numeric(14,2) NOT NULL,
    actual_km numeric(8,1),
    actual_cost numeric(14,2),
    planner text NOT NULL CHECK (planner IN ('heuristic', 'timefold')),
    status text NOT NULL CHECK (status IN ('planned', 'running', 'done', 'superseded')),
    CONSTRAINT route_pkey PRIMARY KEY (route_id),
    CONSTRAINT route_dc_site_id_fkey FOREIGN KEY (dc_site_id) REFERENCES hartland.site (site_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT route_carrier_id_fkey FOREIGN KEY (carrier_id) REFERENCES hartland.carrier (carrier_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT route_vehicle_id_fkey FOREIGN KEY (vehicle_id) REFERENCES hartland.vehicle (vehicle_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT route_superseded_by_route_id_fkey FOREIGN KEY (superseded_by_route_id) REFERENCES hartland.route (route_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.route_stop (
    route_stop_id bigint NOT NULL,
    route_id bigint NOT NULL,
    seq integer NOT NULL,
    shipment_id bigint NOT NULL,
    delivery_point_id bigint NOT NULL,
    planned_arrival timestamptz NOT NULL,
    window_from time,
    window_to time,
    actual_arrival timestamptz,
    status text NOT NULL CHECK (status IN ('delivered', 'late', 'failed', 'moved')),
    CONSTRAINT route_stop_pkey PRIMARY KEY (route_stop_id),
    CONSTRAINT route_stop_route_id_seq_key UNIQUE (route_id, seq),
    CONSTRAINT route_stop_route_id_fkey FOREIGN KEY (route_id) REFERENCES hartland.route (route_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT route_stop_shipment_id_fkey FOREIGN KEY (shipment_id) REFERENCES hartland.shipment (shipment_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT route_stop_delivery_point_id_fkey FOREIGN KEY (delivery_point_id) REFERENCES hartland.delivery_point (delivery_point_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.delivery_event (
    delivery_event_id bigint NOT NULL,
    route_id bigint NOT NULL,
    route_stop_id bigint,
    occurred_at timestamptz NOT NULL,
    kind text NOT NULL CHECK (kind IN ('breakdown', 'late', 'no_show', 'road_closure', 'refused', 'short_picked', 'weather')),
    severity text NOT NULL CHECK (severity IN ('low', 'medium', 'high')),
    description text NOT NULL,
    reported_by text NOT NULL CHECK (reported_by IN ('driver', 'customer', 'dispatcher')),
    CONSTRAINT delivery_event_pkey PRIMARY KEY (delivery_event_id),
    CONSTRAINT delivery_event_route_id_fkey FOREIGN KEY (route_id) REFERENCES hartland.route (route_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT delivery_event_route_stop_id_fkey FOREIGN KEY (route_stop_id) REFERENCES hartland.route_stop (route_stop_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.dispatch_case (
    dispatch_case_id bigint NOT NULL,
    delivery_event_id bigint NOT NULL,
    opened_at timestamptz NOT NULL,
    closed_at timestamptz,
    dispatcher_employee_id bigint NOT NULL,
    resolution text NOT NULL CHECK (resolution IN ('reroute', 'next_day', 'swap_carrier', 'partial')),
    extra_cost numeric(14,2) NOT NULL,
    stops_moved integer NOT NULL,
    stops_slipped integer NOT NULL,
    note text,
    CONSTRAINT dispatch_case_pkey PRIMARY KEY (dispatch_case_id),
    CONSTRAINT dispatch_case_delivery_event_id_fkey FOREIGN KEY (delivery_event_id) REFERENCES hartland.delivery_event (delivery_event_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT dispatch_case_dispatcher_employee_id_fkey FOREIGN KEY (dispatcher_employee_id) REFERENCES hartland.employee (employee_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.dc_invoice (
    dc_invoice_id bigint NOT NULL,
    dc_site_id bigint NOT NULL,
    month date NOT NULL,
    fixed_amount numeric(14,2) NOT NULL,
    cases_handled numeric(12,3) NOT NULL,
    rate_per_case numeric(14,2) NOT NULL,
    amount numeric(14,2) NOT NULL,
    CONSTRAINT dc_invoice_pkey PRIMARY KEY (dc_invoice_id),
    CONSTRAINT dc_invoice_dc_site_id_fkey FOREIGN KEY (dc_site_id) REFERENCES hartland.site (site_id) DEFERRABLE INITIALLY DEFERRED
);

-- ── finance ─────────────────────────────────────────────────────────────────────────────────────────────

CREATE TABLE hartland.invoice (
    invoice_id bigint NOT NULL,
    invoice_no text NOT NULL,
    kind text NOT NULL CHECK (kind IN ('invoice', 'credit_note', 'intercompany')),
    customer_id bigint,
    legal_entity_id bigint NOT NULL,
    issued_on date NOT NULL,
    due_on date NOT NULL,
    net_amount numeric(14,2) NOT NULL,
    vat_amount numeric(14,2) NOT NULL,
    gross_amount numeric(14,2) NOT NULL,
    shipment_id bigint,
    sales_order_id bigint,
    status text NOT NULL CHECK (status IN ('open', 'paid', 'partly_paid', 'overdue', 'written_off')),
    CONSTRAINT invoice_pkey PRIMARY KEY (invoice_id),
    CONSTRAINT invoice_invoice_no_key UNIQUE (invoice_no),
    CONSTRAINT invoice_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES hartland.customer (customer_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT invoice_legal_entity_id_fkey FOREIGN KEY (legal_entity_id) REFERENCES hartland.legal_entity (legal_entity_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT invoice_shipment_id_fkey FOREIGN KEY (shipment_id) REFERENCES hartland.shipment (shipment_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT invoice_sales_order_id_fkey FOREIGN KEY (sales_order_id) REFERENCES hartland.sales_order (sales_order_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.invoice_line (
    invoice_line_id bigint NOT NULL,
    invoice_id bigint NOT NULL,
    sales_order_line_id bigint,
    qty_cases numeric(12,3) NOT NULL,
    net_amount numeric(14,2) NOT NULL,
    vat_rate numeric(5,2) NOT NULL,
    vat_amount numeric(14,2) NOT NULL,
    credit_reason text,
    CONSTRAINT invoice_line_pkey PRIMARY KEY (invoice_line_id),
    CONSTRAINT invoice_line_invoice_id_fkey FOREIGN KEY (invoice_id) REFERENCES hartland.invoice (invoice_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT invoice_line_sales_order_line_id_fkey FOREIGN KEY (sales_order_line_id) REFERENCES hartland.sales_order_line (sales_order_line_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.payment (
    payment_id bigint NOT NULL,
    customer_id bigint NOT NULL,
    received_on date NOT NULL,
    amount numeric(14,2) NOT NULL,
    method text NOT NULL CHECK (method IN ('transfer', 'card', 'prepaid', 'cash')),
    CONSTRAINT payment_pkey PRIMARY KEY (payment_id),
    CONSTRAINT payment_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES hartland.customer (customer_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.payment_allocation (
    payment_id bigint NOT NULL,
    invoice_id bigint NOT NULL,
    amount numeric(14,2) NOT NULL,
    CONSTRAINT payment_allocation_pkey PRIMARY KEY (payment_id, invoice_id),
    CONSTRAINT payment_allocation_payment_id_fkey FOREIGN KEY (payment_id) REFERENCES hartland.payment (payment_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT payment_allocation_invoice_id_fkey FOREIGN KEY (invoice_id) REFERENCES hartland.invoice (invoice_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.dunning (
    dunning_id bigint NOT NULL,
    invoice_id bigint NOT NULL,
    level integer NOT NULL,
    sent_on date NOT NULL,
    CONSTRAINT dunning_pkey PRIMARY KEY (dunning_id),
    CONSTRAINT dunning_invoice_id_fkey FOREIGN KEY (invoice_id) REFERENCES hartland.invoice (invoice_id) DEFERRABLE INITIALLY DEFERRED
);

-- ── orders ──────────────────────────────────────────────────────────────────────────────────────────────

CREATE TABLE hartland.return (
    return_id bigint NOT NULL,
    customer_id bigint NOT NULL,
    sales_order_line_id bigint NOT NULL,
    returned_on date NOT NULL,
    qty_cases numeric(12,3) NOT NULL,
    reason text NOT NULL CHECK (reason IN ('damaged', 'expired', 'wrong')),
    credit_invoice_id bigint,
    CONSTRAINT return_pkey PRIMARY KEY (return_id),
    CONSTRAINT return_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES hartland.customer (customer_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT return_sales_order_line_id_fkey FOREIGN KEY (sales_order_line_id) REFERENCES hartland.sales_order_line (sales_order_line_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT return_credit_invoice_id_fkey FOREIGN KEY (credit_invoice_id) REFERENCES hartland.invoice (invoice_id) DEFERRABLE INITIALLY DEFERRED
);

-- ── finance ─────────────────────────────────────────────────────────────────────────────────────────────

CREATE TABLE hartland.ap_invoice (
    ap_invoice_id bigint NOT NULL,
    supplier_id bigint NOT NULL,
    issued_on date NOT NULL,
    due_on date NOT NULL,
    net_amount numeric(14,2) NOT NULL,
    vat_amount numeric(14,2) NOT NULL,
    ref_kind text NOT NULL CHECK (ref_kind IN ('purchase_order', 'route_batch', 'dc_invoice', 'campaign_cost', 'admin')),
    ref_id bigint,
    paid_on date,
    CONSTRAINT ap_invoice_pkey PRIMARY KEY (ap_invoice_id),
    CONSTRAINT ap_invoice_supplier_id_fkey FOREIGN KEY (supplier_id) REFERENCES hartland.supplier (supplier_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.gl_journal (
    gl_journal_id bigint NOT NULL,
    month date NOT NULL,
    gl_account_id bigint NOT NULL,
    cost_centre_id bigint,
    product_line_id bigint,
    channel text CHECK (channel IN ('big_retail', 'small_retail', 'gas_ka', 'own_shops', 'web', 'vending', 'horeca')),
    amount numeric(14,2) NOT NULL,
    source text NOT NULL CHECK (source IN ('documents', 'allocation', 'manual')),
    CONSTRAINT gl_journal_pkey PRIMARY KEY (gl_journal_id),
    CONSTRAINT gl_journal_gl_account_id_fkey FOREIGN KEY (gl_account_id) REFERENCES hartland.gl_account (gl_account_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT gl_journal_cost_centre_id_fkey FOREIGN KEY (cost_centre_id) REFERENCES hartland.cost_centre (cost_centre_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT gl_journal_product_line_id_fkey FOREIGN KEY (product_line_id) REFERENCES hartland.product_line (product_line_id) DEFERRABLE INITIALLY DEFERRED
);

-- ── marketing ───────────────────────────────────────────────────────────────────────────────────────────

CREATE TABLE hartland.campaign_cost (
    campaign_cost_id bigint NOT NULL,
    campaign_id bigint NOT NULL,
    month date NOT NULL,
    media text NOT NULL CHECK (media IN ('tv', 'outdoor', 'digital', 'instore', 'agency')),
    amount numeric(14,2) NOT NULL,
    ap_invoice_id bigint,
    CONSTRAINT campaign_cost_pkey PRIMARY KEY (campaign_cost_id),
    CONSTRAINT campaign_cost_campaign_id_fkey FOREIGN KEY (campaign_id) REFERENCES hartland.campaign (campaign_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT campaign_cost_ap_invoice_id_fkey FOREIGN KEY (ap_invoice_id) REFERENCES hartland.ap_invoice (ap_invoice_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.promotion_result (
    promotion_id bigint NOT NULL,
    week date NOT NULL,
    baseline_cases numeric(12,3) NOT NULL,
    actual_cases numeric(12,3) NOT NULL,
    uplift_pct numeric(7,2) NOT NULL,
    promotion_cost numeric(14,2) NOT NULL,
    free_goods_cost numeric(14,2) NOT NULL,
    incremental_net_revenue numeric(14,2) NOT NULL,
    incremental_customer_margin numeric(14,2) NOT NULL,
    CONSTRAINT promotion_result_pkey PRIMARY KEY (promotion_id, week),
    CONSTRAINT promotion_result_promotion_id_fkey FOREIGN KEY (promotion_id) REFERENCES hartland.promotion (promotion_id) DEFERRABLE INITIALLY DEFERRED
);

-- ── field ───────────────────────────────────────────────────────────────────────────────────────────────

CREATE TABLE hartland.rep_prompt (
    rep_prompt_id bigint NOT NULL,
    employee_id bigint NOT NULL,
    customer_id bigint NOT NULL,
    visit_id bigint,
    generated_on date NOT NULL,
    kind text NOT NULL CHECK (kind IN ('mandatory_promotion', 'unsupplied_items', 'pos_placement', 'competitor_response', 'ai_tip', 'debt')),
    prompt_rule_id bigint,
    priority integer NOT NULL,
    payload text NOT NULL,
    explanation text NOT NULL,
    outcome text NOT NULL CHECK (outcome IN ('successful', 'unsuccessful', 'not_discussed', 'rejected', 'open')),
    outcome_reason text,
    classified_on date,
    generated_by text NOT NULL CHECK (generated_by IN ('rules', 'agent')),
    CONSTRAINT rep_prompt_pkey PRIMARY KEY (rep_prompt_id),
    CONSTRAINT rep_prompt_employee_id_fkey FOREIGN KEY (employee_id) REFERENCES hartland.employee (employee_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT rep_prompt_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES hartland.customer (customer_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT rep_prompt_visit_id_fkey FOREIGN KEY (visit_id) REFERENCES hartland.visit (visit_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT rep_prompt_prompt_rule_id_fkey FOREIGN KEY (prompt_rule_id) REFERENCES hartland.prompt_rule (prompt_rule_id) DEFERRABLE INITIALLY DEFERRED
);

-- ── shops ───────────────────────────────────────────────────────────────────────────────────────────────

CREATE TABLE hartland.shop_receipt (
    shop_receipt_id bigint NOT NULL,
    site_id bigint NOT NULL,
    at timestamptz NOT NULL,
    register_no integer NOT NULL,
    gross_amount numeric(14,2) NOT NULL,
    payment_method text NOT NULL CHECK (payment_method IN ('transfer', 'card', 'prepaid', 'cash')),
    CONSTRAINT shop_receipt_pkey PRIMARY KEY (shop_receipt_id),
    CONSTRAINT shop_receipt_site_id_fkey FOREIGN KEY (site_id) REFERENCES hartland.site (site_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.shop_receipt_line (
    shop_receipt_line_id bigint NOT NULL,
    shop_receipt_id bigint NOT NULL,
    sku_id bigint,
    menu_item_id bigint,
    qty numeric(12,3) NOT NULL,
    unit_price_gross numeric(14,2) NOT NULL,
    vat_rate numeric(5,2) NOT NULL,
    CONSTRAINT shop_receipt_line_pkey PRIMARY KEY (shop_receipt_line_id),
    CONSTRAINT shop_receipt_line_shop_receipt_id_fkey FOREIGN KEY (shop_receipt_id) REFERENCES hartland.shop_receipt (shop_receipt_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT shop_receipt_line_sku_id_fkey FOREIGN KEY (sku_id) REFERENCES hartland.sku (sku_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT shop_receipt_line_menu_item_id_fkey FOREIGN KEY (menu_item_id) REFERENCES hartland.menu_item (menu_item_id) DEFERRABLE INITIALLY DEFERRED
);

