CREATE TABLE hartland.document_golden (
    document_id bigint NOT NULL,
    schema text NOT NULL,
    payload jsonb NOT NULL,
    mentions jsonb NOT NULL,
    CONSTRAINT document_golden_pkey PRIMARY KEY (document_id),
    CONSTRAINT document_golden_document_id_fkey FOREIGN KEY (document_id) REFERENCES hartland.document (document_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.complaint (
    complaint_id bigint NOT NULL,
    code text NOT NULL,
    customer_id bigint NOT NULL,
    document_id bigint,
    received_on date NOT NULL,
    kind text NOT NULL CHECK (kind IN ('quality', 'delivery', 'service', 'price', 'other')),
    sku_id bigint,
    sales_order_id bigint,
    invoice_id bigint,
    shipment_id bigint,
    severity text NOT NULL CHECK (severity IN ('low', 'medium', 'high')),
    status text NOT NULL CHECK (status IN ('open', 'acknowledged', 'resolved', 'rejected')),
    resolution text,
    resolved_on date,
    owner_employee_id bigint,
    source text NOT NULL CHECK (source IN ('generated', 'pipeline')),
    CONSTRAINT complaint_pkey PRIMARY KEY (complaint_id),
    CONSTRAINT complaint_code_key UNIQUE (code),
    CONSTRAINT complaint_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES hartland.customer (customer_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT complaint_document_id_fkey FOREIGN KEY (document_id) REFERENCES hartland.document (document_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT complaint_sku_id_fkey FOREIGN KEY (sku_id) REFERENCES hartland.sku (sku_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT complaint_sales_order_id_fkey FOREIGN KEY (sales_order_id) REFERENCES hartland.sales_order (sales_order_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT complaint_invoice_id_fkey FOREIGN KEY (invoice_id) REFERENCES hartland.invoice (invoice_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT complaint_shipment_id_fkey FOREIGN KEY (shipment_id) REFERENCES hartland.shipment (shipment_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT complaint_owner_employee_id_fkey FOREIGN KEY (owner_employee_id) REFERENCES hartland.employee (employee_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.return_request_hdr (
    rr_request_number bigint NOT NULL,
    rr_customer_sk bigint NOT NULL,
    rr_order_number bigint NOT NULL,
    rr_channel text NOT NULL,
    rr_requested_date date NOT NULL,
    document_id bigint,
    source text NOT NULL CHECK (source IN ('generated', 'pipeline')),
    CONSTRAINT return_request_hdr_pkey PRIMARY KEY (rr_request_number),
    CONSTRAINT return_request_hdr_rr_customer_sk_fkey FOREIGN KEY (rr_customer_sk) REFERENCES hartland.customer (customer_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT return_request_hdr_rr_order_number_fkey FOREIGN KEY (rr_order_number) REFERENCES hartland.sales_order (sales_order_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT return_request_hdr_document_id_fkey FOREIGN KEY (document_id) REFERENCES hartland.document (document_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.return_request_line (
    rl_line_id bigint NOT NULL,
    rl_request_number bigint NOT NULL,
    rl_line_no integer NOT NULL,
    rl_item_sk bigint NOT NULL,
    rl_quantity integer NOT NULL,
    rl_unit_price numeric(12,2) NOT NULL,
    rl_reason text NOT NULL CHECK (rl_reason IN ('damaged', 'did_not_arrive', 'wrong_size', 'other')),
    rl_requested_resolution text NOT NULL CHECK (rl_requested_resolution IN ('refund', 'exchange', 'replacement')),
    rl_requested_variant_sk bigint,
    rl_state text NOT NULL CHECK (rl_state IN ('received', 'rejected', 'settling', 'awaiting_goods', 'goods_received', 'not_returned', 'closed')),
    rl_way text,
    rl_customer_sk bigint NOT NULL,
    CONSTRAINT return_request_line_pkey PRIMARY KEY (rl_line_id),
    CONSTRAINT return_request_line_rl_request_number_fkey FOREIGN KEY (rl_request_number) REFERENCES hartland.return_request_hdr (rr_request_number) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT return_request_line_rl_item_sk_fkey FOREIGN KEY (rl_item_sk) REFERENCES hartland.sku (sku_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT return_request_line_rl_requested_variant_sk_fkey FOREIGN KEY (rl_requested_variant_sk) REFERENCES hartland.sku (sku_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT return_request_line_rl_customer_sk_fkey FOREIGN KEY (rl_customer_sk) REFERENCES hartland.customer (customer_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.return_receipt (
    rc_receipt_id bigint NOT NULL,
    rc_line_id bigint NOT NULL,
    rc_received_date date NOT NULL,
    rc_item_sk bigint NOT NULL,
    rc_quantity integer NOT NULL,
    rc_condition text NOT NULL CHECK (rc_condition IN ('ok', 'damaged', 'missing')),
    CONSTRAINT return_receipt_pkey PRIMARY KEY (rc_receipt_id),
    CONSTRAINT return_receipt_rc_line_id_fkey FOREIGN KEY (rc_line_id) REFERENCES hartland.return_request_line (rl_line_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT return_receipt_rc_item_sk_fkey FOREIGN KEY (rc_item_sk) REFERENCES hartland.sku (sku_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.credit_note (
    cn_credit_note_id bigint NOT NULL,
    cn_line_id bigint NOT NULL,
    cn_customer_sk bigint NOT NULL,
    cn_issued_date date NOT NULL,
    cn_amount numeric(12,2) NOT NULL,
    cn_status text NOT NULL CHECK (cn_status IN ('issued', 'paid')),
    CONSTRAINT credit_note_pkey PRIMARY KEY (cn_credit_note_id),
    CONSTRAINT credit_note_cn_line_id_fkey FOREIGN KEY (cn_line_id) REFERENCES hartland.return_request_line (rl_line_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT credit_note_cn_customer_sk_fkey FOREIGN KEY (cn_customer_sk) REFERENCES hartland.customer (customer_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.refund_payment (
    rp_payment_id bigint NOT NULL,
    rp_credit_note_id bigint NOT NULL,
    rp_paid_date date NOT NULL,
    rp_amount numeric(12,2) NOT NULL,
    CONSTRAINT refund_payment_pkey PRIMARY KEY (rp_payment_id),
    CONSTRAINT refund_payment_rp_credit_note_id_fkey FOREIGN KEY (rp_credit_note_id) REFERENCES hartland.credit_note (cn_credit_note_id) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE hartland.replacement_shipment (
    rs_shipment_id bigint NOT NULL,
    rs_line_id bigint NOT NULL,
    rs_item_sk bigint NOT NULL,
    rs_quantity integer NOT NULL,
    rs_shipped_date date NOT NULL,
    CONSTRAINT replacement_shipment_pkey PRIMARY KEY (rs_shipment_id),
    CONSTRAINT replacement_shipment_rs_line_id_fkey FOREIGN KEY (rs_line_id) REFERENCES hartland.return_request_line (rl_line_id) DEFERRABLE INITIALLY DEFERRED,
    CONSTRAINT replacement_shipment_rs_item_sk_fkey FOREIGN KEY (rs_item_sk) REFERENCES hartland.sku (sku_id) DEFERRABLE INITIALLY DEFERRED
);

-- ── views ───────────────────────────────────────────────────────────────────────────────────────────────

SET search_path TO hartland;

CREATE MATERIALIZED VIEW hartland.sales_pl AS
-- sales_pl — an order line with its P/L, from gross revenue to the product margin (contracts §4).
-- The `sales` entity, the `sales` cubelet and the H-L hand SQL all read it. The trade-spend columns are sums over the
-- line's discount list by kind; `retro` rolls into discount_individual (contracts §4, the review-189 note), while the
-- GL keeps it on its own account. Money in CZK without VAT.
--
-- The rep is whoever answers for the sale on the order day: in small retail (station shops included, a sub-channel)
-- the rep assigned to the store's area; in the KAM channels (big retail, gas KA, vending, HoReCa) the KAM assigned to
-- the customer; else (own shops, the web, an area or customer without one) whoever took the order. A rep still sees
-- the chain stores of their area, through `area_id`, not through this column. The area: the store's, else the
-- delivery point's okres's.
SELECT
    l.sales_order_line_id AS line_id,
    o.sales_order_id AS order_id,
    o.ordered_on,
    delivered.delivered_on,
    o.channel,
    c.sub_channel,
    o.customer_id,
    o.delivery_point_id,
    dp.store_id,
    l.sku_id,
    p.product_line_id,
    pl.brand_id,
    CASE
        WHEN o.channel = 'small_retail' THEN COALESCE(rep.employee_id, o.taken_by_employee_id)
        ELSE COALESCE(kam.employee_id, o.taken_by_employee_id)
    END AS rep_employee_id,
    COALESCE(st.area_id, ao.area_id) AS area_id,
    ok.code AS okres_code,
    o.dc_site_id,
    l.qty_cases AS cases,
    l.qty_pieces AS pieces,
    l.list_price_case,
    m.gross_revenue,
    d.discount_volume,
    d.discount_cross_sell,
    d.discount_agreed,
    d.discount_individual,
    d.discount_promotion,
    d.free_goods_value,
    m.gross_revenue - d.total AS net_revenue,
    m.delivery_cost,
    m.warehouse_cost,
    m.gross_revenue - d.total - m.delivery_cost - m.warehouse_cost AS customer_margin,
    m.cogs,
    m.marketing_cost,
    m.gross_revenue - d.total - m.delivery_cost - m.warehouse_cost - m.cogs - m.marketing_cost AS product_margin,
    l.vat_rate,
    ROUND((m.gross_revenue - d.total) * l.vat_rate / 100, 2) AS vat
FROM sales_order_line l
JOIN sales_order o ON o.sales_order_id = l.sales_order_id
JOIN customer c ON c.customer_id = o.customer_id
JOIN delivery_point dp ON dp.delivery_point_id = o.delivery_point_id
JOIN okres ok ON ok.okres_id = dp.okres_id
LEFT JOIN area_okres ao ON ao.okres_id = dp.okres_id
LEFT JOIN store st ON st.store_id = dp.store_id
JOIN sku s ON s.sku_id = l.sku_id
JOIN product p ON p.product_id = s.product_id
JOIN product_line pl ON pl.product_line_id = p.product_line_id
CROSS JOIN LATERAL (
    SELECT
        ROUND(l.list_price_case * l.qty_cases, 2) AS gross_revenue,
        ROUND(COALESCE(l.delivery_cost_case, 0) * l.qty_cases, 2) AS delivery_cost,
        ROUND(COALESCE(l.warehouse_cost_case, 0) * l.qty_cases, 2) AS warehouse_cost,
        ROUND((l.purchase_price_case + l.inbound_cost_case) * l.qty_cases, 2) AS cogs,
        ROUND(COALESCE(l.marketing_cost_case, 0) * l.qty_cases, 2) AS marketing_cost
) m
CROSS JOIN LATERAL (
    SELECT
        COALESCE(SUM(x.amount_line) FILTER (WHERE x.kind = 'volume'), 0) AS discount_volume,
        COALESCE(SUM(x.amount_line) FILTER (WHERE x.kind = 'cross_sell'), 0) AS discount_cross_sell,
        COALESCE(SUM(x.amount_line) FILTER (WHERE x.kind = 'agreed'), 0) AS discount_agreed,
        COALESCE(SUM(x.amount_line) FILTER (WHERE x.kind IN ('individual', 'retro')), 0) AS discount_individual,
        COALESCE(SUM(x.amount_line) FILTER (WHERE x.kind = 'promotion'), 0) AS discount_promotion,
        COALESCE(SUM(x.amount_line) FILTER (WHERE x.kind = 'free_goods'), 0) AS free_goods_value,
        COALESCE(SUM(x.amount_line), 0) AS total
    FROM sales_order_line_discount x
    WHERE x.sales_order_line_id = l.sales_order_line_id
) d
LEFT JOIN LATERAL (
    SELECT (MAX(sh.delivered_at) AT TIME ZONE 'Europe/Prague')::date AS delivered_on
    FROM shipment sh
    WHERE sh.sales_order_id = o.sales_order_id
) delivered ON true
LEFT JOIN LATERAL (
    SELECT a.employee_id
    FROM assignment a
    WHERE a.kind = 'rep_area' AND a.area_id = st.area_id AND o.ordered_on BETWEEN a.valid_from AND a.valid_to
    ORDER BY a.valid_from DESC
    LIMIT 1
) rep ON true
LEFT JOIN LATERAL (
    SELECT a.employee_id
    FROM assignment a
    WHERE a.kind = 'kam_customer' AND a.customer_id = o.customer_id
      AND o.ordered_on BETWEEN a.valid_from AND a.valid_to
    ORDER BY a.valid_from DESC
    LIMIT 1
) kam ON true
WITH NO DATA;

CREATE MATERIALIZED VIEW hartland.trade_spend AS
-- trade_spend — the trade spend by what caused it: a month × a channel × a discount kind × its code (the promotion's,
-- the agreement's or the tier's) × whose budget bears it (contracts §4; NH-D6). Joining `promotion` → `campaign`
-- gives the spend by campaign and mechanic. Money in CZK without VAT.
SELECT
    date_trunc('month', o.ordered_on)::date AS month,
    o.channel,
    x.kind,
    x.code,
    x.promotion_id,
    x.price_agreement_id,
    x.budget,
    COUNT(*) AS lines,
    SUM(l.qty_cases) AS cases,
    SUM(x.amount_line) AS amount
FROM sales_order_line_discount x
JOIN sales_order_line l ON l.sales_order_line_id = x.sales_order_line_id
JOIN sales_order o ON o.sales_order_id = l.sales_order_id
GROUP BY 1, o.channel, x.kind, x.code, x.promotion_id, x.price_agreement_id, x.budget
WITH NO DATA;

CREATE MATERIALIZED VIEW hartland.route_current AS
-- route_current — the route version current at the end of its day: the morning plan, or its last re-plan (a version
-- nothing supersedes), with its stops' outcomes. Every delivered stop belongs to one of these (05 §7).
SELECT
    r.route_id,
    r.dc_site_id,
    r.day,
    r.carrier_id,
    r.vehicle_id,
    r.version,
    r.planned_departure,
    r.planned_km,
    r.planned_stops,
    r.planned_cost,
    r.actual_km,
    r.actual_cost,
    r.planner,
    r.status,
    COUNT(s.route_stop_id) AS stops,
    COUNT(s.route_stop_id) FILTER (WHERE s.status = 'delivered') AS stops_delivered,
    COUNT(s.route_stop_id) FILTER (WHERE s.status = 'late') AS stops_late,
    COUNT(s.route_stop_id) FILTER (WHERE s.status = 'failed') AS stops_failed,
    COUNT(s.route_stop_id) FILTER (WHERE s.status = 'moved') AS stops_moved
FROM route r
LEFT JOIN route_stop s ON s.route_id = r.route_id
WHERE r.superseded_by_route_id IS NULL
GROUP BY r.route_id
WITH NO DATA;

CREATE MATERIALIZED VIEW hartland.receivable AS
-- receivable — an invoice with what is paid and what is open, as of the world's last day: the latest invoice or
-- payment in the database (not the wall clock, so a rebuild gives the same rows). Days overdue and the ageing bucket
-- count from the due date; a credit note is a negative receivable, in the bucket `credit` until it is settled.
WITH as_of AS (
    SELECT COALESCE(
        GREATEST((SELECT MAX(issued_on) FROM invoice), (SELECT MAX(received_on) FROM payment)),
        CURRENT_DATE
    ) AS day
)
SELECT
    i.invoice_id,
    i.invoice_no,
    i.kind,
    i.customer_id,
    c.channel,
    i.issued_on,
    i.due_on,
    i.gross_amount,
    COALESCE(paid.amount, 0) AS paid_amount,
    i.gross_amount - COALESCE(paid.amount, 0) AS open_amount,
    as_of.day AS as_of,
    CASE WHEN i.gross_amount - COALESCE(paid.amount, 0) > 0 THEN GREATEST(as_of.day - i.due_on, 0) ELSE 0 END
        AS days_overdue,
    CASE
        WHEN i.kind = 'credit_note' AND i.gross_amount - COALESCE(paid.amount, 0) <> 0 THEN 'credit'
        WHEN i.gross_amount - COALESCE(paid.amount, 0) <= 0 THEN 'paid'
        WHEN as_of.day <= i.due_on THEN 'not_due'
        WHEN as_of.day - i.due_on <= 30 THEN '1_30'
        WHEN as_of.day - i.due_on <= 60 THEN '31_60'
        WHEN as_of.day - i.due_on <= 90 THEN '61_90'
        ELSE 'over_90'
    END AS ageing_bucket
FROM invoice i
CROSS JOIN as_of
LEFT JOIN customer c ON c.customer_id = i.customer_id
LEFT JOIN (
    SELECT invoice_id, SUM(amount) AS amount FROM payment_allocation GROUP BY invoice_id
) paid ON paid.invoice_id = i.invoice_id
WHERE i.kind <> 'intercompany'
WITH NO DATA;

CREATE VIEW hartland.return_request AS
-- return_request — the return request with its state derived from its lines (the automation extension's view, taken
-- over with its columns and its rule; `document_id` and `source` appended): `received` while any line is received (or
-- none has arrived yet), `closed` when every line is rejected, not_returned or closed, `decided` in between. The key
-- of the return flow is the line, so the header keeps no state of its own.
SELECT
    h.rr_request_number,
    h.rr_customer_sk,
    h.rr_order_number,
    h.rr_channel,
    h.rr_requested_date,
    CASE
        WHEN COUNT(l.rl_line_id) = 0 OR BOOL_OR(l.rl_state = 'received') THEN 'received'
        WHEN BOOL_AND(l.rl_state IN ('rejected', 'not_returned', 'closed')) THEN 'closed'
        ELSE 'decided'
    END::text AS rr_state,
    h.document_id,
    h.source
FROM return_request_hdr h
LEFT JOIN return_request_line l ON l.rl_request_number = h.rr_request_number
GROUP BY h.rr_request_number;

RESET search_path;
